  "objectives": [
    {
      "id": 1,
      "objective": "Research materials compatibility: 304 vs 316L stainless steel, copper, graphite interactions with molten copper alloys (C63000) and aluminium alloys. Wetting, sticking, contamination, and galling concerns.",
