      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 2,
      "objective": "Research glass properties: fused quartz vs borosilicate 3.3 thermal shock resistance, behavior when contacted by molten metal at 1000°C, cost comparison.",
      "rationale": "Design C uses glass and the user needs to know if quartz is viable and whether metal is clearly superior.",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 3,
      "objective": "Research seal materials: temperature limits (continuous and excursion) for FKM, VMQ, EPDM, FFKM, PTFE. Vacuum compatibility and permeation rates. Metal KF seals and spring-energised seals.",
      "rationale": "Seals are critical failure points - the original EPDM seal burned. Need quantitative temperature and vacuum performance data.",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 4,
      "objective": "Perform thermal analysis: heat transfer from hot bronze shot to container, puck, and seals. Estimate temperatures and cooling requirements.",
      "rationale": "Need to verify that proposed designs keep seals below temperature limits with specific thermal mass and geometry.",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 5,
      "objective": "Research valve options and powder collection practices in gas atomization systems (HPGA, VIGA/EIGA, AMAZEMET rePOWDER). How do commercial systems protect collection containers?",
      "rationale": "User asks whether a valve is needed and what type, plus what commercial atomizers use.",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 6,
      "objective": "Research ISO-KF vs tri-clamp sealing: leak rates, behavior under vacuum/pressure cycling, testing methods (rate-of-rise, helium leak detection).",
      "rationale": "The joint cycles between 10 mbar absolute and +150 mbar gauge - need to verify seal integrity.",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 7,
      "objective": "Synthesize findings, rank designs A/B/C, recommend modifications, and create final answer with artifacts.",
      "rationale": "Final deliverable combining all research into actionable engineering recommendations.",
      "status": "pending",
      "result": null,
      "evaluation": null
    }
  ]
}"}

